<?php
declare(strict_types=1);
require __DIR__.'/bootstrap.php';
use AISkillsHub\Core\Operations\Workbench;
use AISkillsHub\Core\Operations\Health;
use AISkillsHub\Core\Discovery\Settings;
$bench=new Workbench($submissionQuery,$submissions,$core->get('community_query'),$community,$developerQuery,$developers);
$health=new Health($db,$core->migrator(),new AISkillsHub\Core\Sources\ImportStore($db,$core->migrator()));
$member=p12_user('workbench');$limited=p12_user('limited');$skill=p12_skill('editorial');
$payload=['kind'=>'submit','locale'=>'en_US','source_kind'=>'manual','name'=>'Workbench QA '.$run,'summary'=>'Private synthetic queue record','notes'=>'Review only, never auto publish'];
wp_set_current_user($member);$one=$submissions->save(0,$payload,0,'submit',p12_key());$two=$submissions->save(0,$payload+[],0,'submit',p12_key());
p12_case('workbench_capability_partition_and_no_approval_bulk',function()use($bench,$member,$limited,$admin){wp_set_current_user($member);p12_assert(Workbench::available()===[],'Ordinary subscriber sees no queues');get_userdata($limited)->add_cap(Workbench::CAP);get_userdata($limited)->add_cap('aish_manage_submissions');wp_set_current_user($limited);p12_assert(array_keys(Workbench::available())===['submissions'],'Only dedicated submission queue');p12_reject(fn()=>$bench->listing('reviews'),'Missing review capability denied');p12_reject(fn()=>$bench->batch('submissions',[['id'=>1,'revision'=>1]],'accept','Reviewed feedback','','other',bin2hex(random_bytes(16))),'Bulk acceptance not available');wp_set_current_user($admin);p12_assert(count(Workbench::available())===6,'Admin has six distinct queues');});
p12_case('workbench_partial_batch_cas_replay_preserves_private_content',function()use($bench,$one,$two,$admin,$submissions,$skill){wp_set_current_user($admin);$key=bin2hex(random_bytes(16));$rows=[['id'=>(int)$one['id'],'revision'=>(int)$one['revision']],['id'=>(int)$two['id'],'revision'=>(int)$two['revision']+1]];$before=p12_skill_fingerprint($skill);$r=$bench->batch('submissions',$rows,'reviewing','Synthetic review started','','other',$key);p12_assert(count($r)===2&&$r[0]['success']&&!$r[1]['success'],'One valid, one stale result');$again=$bench->batch('submissions',$rows,'reviewing','Synthetic review started','','other',$key);p12_assert($again[0]['success']&&!$again[1]['success'],'Replay retains completed row and rejects stale');p12_assert(p12_skill_fingerprint($skill)===$before,'No published Skill overwrite');p12_assert(get_post_status((int)$one['id'])==='private','Native Inbox stays private');p12_assert(count($bench->history('submissions',(int)$one['id'])['items'])===2,'One submission and one review workflow event');});
p12_case('workbench_search_filters_and_unknown_types_fail_closed',function()use($bench,$admin,$one){wp_set_current_user($admin);$result=$bench->listing('submissions',['q'=>'Workbench QA','state'=>'in_review']);p12_assert(in_array((int)$one['id'],array_map('intval',array_column($result['items'],'id')),true),'Search and state reused');p12_reject(fn()=>$bench->listing('sql_union'),'Unknown type rejected');p12_reject(fn()=>$bench->listing('submissions',['state'=>'published']),'No made-up published submission state');});
wp_set_current_user($admin);$repo=$management->saveRepository(null,'qa-'.$run,'operations-health');$sourceSkill=p12_skill('source',true,true,'skills/qa/SKILL.md');
$import=$db->insert('imports',['skill_id'=>$sourceSkill,'repository_id'=>$repo,'source_path'=>'skills/qa/SKILL.md','file_sha'=>str_repeat('a',40),'commit_sha'=>str_repeat('b',40),'metadata_json'=>'{}','findings_json'=>'[]','source_status'=>'missing','change_status'=>'updated','last_seen_job'=>null,'created_at'=>gmdate('Y-m-d H:i:s'),'updated_at'=>gmdate('Y-m-d H:i:s')]);
p12_case('source_health_snapshot_ack_is_audit_only_and_no_network',function()use($health,$db,$import,$sourceSkill,$externalRequests){$before=p12_skill_fingerprint($sourceSkill);$row=$db->row('SELECT * FROM '.$db->table('imports').' WHERE id=%d',[$import]);$hash=AISkillsHub\Core\Sources\ImportStore::sourceRevision($row);$key=bin2hex(random_bytes(16));$health->acknowledge($import,$hash,'checked_source',$key);$health->acknowledge($import,$hash,'checked_source',$key);$rows=$health->listing('sources',1,'missing')['items'];$got=p12_find($rows,$import);p12_assert($got&&$got['acknowledgement']['reason']==='checked_source','Current fingerprint acknowledged');p12_assert(p12_skill_fingerprint($sourceSkill)===$before,'Skill/translation/version untouched');p12_assert($db->row('SELECT * FROM '.$db->table('imports').' WHERE id=%d',[$import])===$row,'Import evidence not rewritten');p12_reject(fn()=>$health->acknowledge($import,str_repeat('c',64),'checked_source',bin2hex(random_bytes(16))),'Stale evidence rejected');p12_assert($externalRequests===0,'No HTTP called');});
p12_case('source_retry_limits_and_paused_source_not_queued',function()use($health,$db,$repo,$admin,$member){wp_set_current_user($member);p12_reject(fn()=>$health->listing('sources'),'Health capability enforced');wp_set_current_user($admin);$db->execute('UPDATE '.$db->table('repositories').' SET sync_enabled=0 WHERE id=%d',[$repo]);$r=$health->retry([$repo]);p12_assert(!$r[0]['success'],'Paused source retry refused');p12_reject(fn()=>$health->retry([$repo,$repo]),'Duplicate batch rejected');p12_reject(fn()=>$health->retry(['https://127.0.0.1/private']),'Arbitrary URL rejected');});
$original=Settings::snapshot();$original['published']=Settings::validate($original['published']);
p12_case('home_draft_history_live_gate_and_stale_configuration',function()use($settings,$admin,$member,$skill,$management,$original){wp_set_current_user($admin);$p=$original['published'];foreach(['en_US','zh_CN']as$l){foreach($p['home'][$l]as&$module){if($module['key']==='collections'){$module['enabled']=true;$module['source']='skills';$module['selected_ids']=[$skill];$module['editorial_reason']='Synthetic editorial selection';}}unset($module);}$saved=$settings->save($p,$original['revision'],'draft');p12_assert(Settings::snapshot()['published']===$original['published'],'Draft does not alter live config');p12_assert(count($settings->history())>0,'Draft audit recorded');p12_reject(fn()=>$settings->save($p,$original['revision'],'publish'),'Stale config CAS');$s=Settings::snapshot();$settings->save($p,$s['revision'],'publish');p12_assert(Settings::snapshot()['published']===$p,'Approved live settings committed');$management->archiveSkill($skill,p12_skill_revision($skill));p12_assert(count($settings->issues($p))>0,'Archived selection immediately unavailable');$s=Settings::snapshot();p12_reject(fn()=>$settings->save($p,$s['revision'],'publish'),'Unavailable manual selection not republished');wp_set_current_user($member);p12_reject(fn()=>$settings->history(),'Settings audit private');});
// Restore the prior valid production-shaped home configuration, without erasing audit history.
wp_set_current_user($admin);$s=Settings::snapshot();$settings->save($original['published'],$s['revision'],'publish');
p12_report('Real WordPress/MySQL capability-partitioned workflow queues, source-health audit-only actions and home draft/publication controls');
